// Two buyers compete for 6 tonnes each when only 9.5 tonnes remain.
$workers=[];
foreach([2,5] as $buyer){
 $desc=[1=>['pipe','w'],2=>['pipe','w']];
 $cmd=[PHP_BINARY,'-n','-d','session.save_path='.sys_get_temp_dir(),'-d','extension_dir='.ini_get('extension_dir'),'-d','extension=ctype.so','-d','extension=fileinfo.so','-d','extension=mbstring.so','-d','extension=pdo.so','-d','extension=mysqlnd.so','-d','extension=pdo_mysql.so','-d','extension=curl.so',__DIR__.'/reserve_driver.php',(string)$batch,(string)$buyer];
 $proc=proc_open($cmd,$desc,$pipes,null,getenv());$workers[]=[$proc,$pipes];
}
$accepted=0;$rejected=0;
foreach($workers as [$proc,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$rc=proc_close($proc);if($rc===0 && str_contains($out,'CREATED:')){$accepted++;}elseif($rc===2 && str_contains($out,'REJECTED')){$rejected++;}else{throw new RuntimeException('Concurrent worker failed: '.$out.$err);}}
check($accepted===1 && $rejected===1,'Concurrent competing buyers cannot oversell stock');
check((int)batch_detail($batch)['reserved_g']===6000000,'Concurrent reservation leaves exactly the winning quantity reserved');
echo "\nALL {$passed} WORKFLOW AND SECURITY CHECKS PASSED.\n";
